prompt:
Crie um componente Spinner para um projeto React + Tailwind CSS com shadcn/ui (estilo "New York", acessível via Radix UI).

Alternativa recomendada (registro oficial open source, licença MIT): instale direto com o CLI shadcn:

npx shadcn add spinner

Documentação oficial: https://ui.shadcn.com/docs/components/spinner

Implementação de referência (MIT — shadcn/ui):

import { cn } from "cn"
import { Loader2Icon } from "lucide-react"

function Spinner({ className, ...props }: React.ComponentProps<"svg">) {
  return (
    <Loader2Icon
      role="status"
      aria-label="Loading"
      className={cn("size-4 animate-spin", className)}
      {...props}
    />
  )
}

export { Spinner }
